Script1:
triggerer.Do(
(){
  SetTeam( 1 );
this.am_ally = 1;
  globals.always_serialised += this;
  AddToPlayerWakeGroup();
  this.warpath = FindClosestObject( "Metadata/Terrain/Gallows/Act5/5_16/Objects/AlliedPath" );
  SetPathObject( warpath );
  SetStateTo( pathing, 1 );
} );

triggerer.Do(
(){
  globals.always_serialised += this;
  this.am_enemy = 1;
  AddToPlayerWakeGroup();
  this.warpath = FindClosestObject( "Metadata/Terrain/Gallows/Act5/5_16/Objects/EnemyPath" );
  SetPathObject( warpath );
  SetStateTo( pathing, 1 );
} );

triggerer.AddLifeOnDeath(
	{
	SetQuestFlagForAll( G4_1_1TamedBeastRareLandmarkDefeated );
	DropQuestItem( 'Metadata/Items/Gems/SkillGemUncut', 0, G4_1_1TamedBeastRareLandmarkDefeated, G4_1_1BeastPenSkillGemPickedUp );		globals.secret_room_marker.SetStateTo( secret_activated, 1 );
	}, false, true );

triggerer.StartImmunityPhase( 0, 1, 1, 1, 0, 0, 0 );
triggerer.RotateBy( 15, true, true );
triggerer.DoAction( WalkEmergeKrutogExpedition, globals.krutog_sulphite_path_start, true, true, true );
triggerer.AddOnActionEnd( { EndImmunityPhase(); }, true );
triggerer.SetLocation( globals.krutog_sulphite_path_start, true );
